{"output":""""Keyword Chip Widget - Single removable parameter chip.

This module provides a chip widget for displaying parameter keywords
with a remove button. Follows Fluent Design principles with
theme-aware styling.

Example:
    >>> chip = KeywordChip("glucose")
    >>> chip.remove_clicked.connect(lambda text: print(f"Remove: {text}"))
    >>> chip.show()
"""

from PySide6.QtCore import Qt, Signal
from PySide6.QtWidgets import (
    QHBoxLayout,
    QLabel,
    QPushButton,
    QSizePolicy,
    QWidget,
)

from kris_ui.styles.colors import DARK_THEME, LIGHT_THEME
from kris_ui.styles.theme_manager import get_system_theme


class KeywordChip(QWidget):
    """Chip widget displaying a parameter name with remove button.

    Displays a parameter keyword as a styled chip with an accent-color
    background and an x button to remove it. Theme-aware styling is
    applied based on system preference.

    Signals:
        remove_clicked: Emitted when remove button is clicked.
            Provides the chip's text as argument.

    Example:
        >>> chip = KeywordChip("sodium")
        >>> chip.remove_clicked.connect(handle_remove)
        >>> chip.text
        'sodium'
    """

    _BORDER_RADIUS: int = 12
    _FONT_SIZE: int = 13

    remove_clicked = Signal(str)

    def __init__(self, text: str, parent: QWidget | None = None) -> None:
        """Initialize the keyword chip.

        Args:
            text: The parameter name to display.
            parent: Optional parent widget.
        """
        super().__init__(parent)
        self._text = text
        self.setObjectName("KeywordChip")
        self._setup_ui()
        self._apply_theme()

    def _setup_ui(self) -> None:
        """Set up widget layout with label and remove button."""
        layout = QHBoxLayout(self)
        layout.setContentsMargins(10, 4, 6, 4)
        layout.setSpacing(4)

        # Text label
        self._label = QLabel(self._text)
        self._label.setObjectName("KeywordChipLabel")
        layout.addWidget(self._label)

        # Remove button - matches FileChipDelegate._BUTTON_SIZE for visual consistency
        self._remove_button = QPushButton("×")
        self._remove_button.setObjectName("KeywordChipRemoveButton")
        self._remove_button.setFixedSize(24, 24)
        self._remove_button.setCursor(Qt.CursorShape.PointingHandCursor)
        self._remove_button.clicked.connect(self._on_remove_clicked)
        layout.addWidget(self._remove_button)

        self.setSizePolicy(QSizePolicy.Policy.Maximum, QSizePolicy.Policy.Fixed)
        self.setFixedHeight(32)

    def _on_remove_clicked(self) -> None:
        """Handle remove button click."""
        self.remove_clicked.emit(self._text)

    def _apply_theme(self) -> None:
        """Apply theme-aware styling."""
        theme = get_system_theme()
        colors = DARK_THEME if theme == "dark" else LIGHT_THEME
        text_color = "#FFFFFF"

        # All styling in one stylesheet on the widget
        self.setStyleSheet(
            f"""
            QWidget#KeywordChip {{
                background-color: {colors.accent};
                border-radius: {self._BORDER_RADIUS}px;
            }}
            QLabel#KeywordChipLabel {{
                color: {text_color};
                font-size: {self._FONT_SIZE}px;
                font-weight: 500;
                background: transparent;
            }}
            QPushButton#KeywordChipRemoveButton {{
                background-color: transparent;
                border: none;
                border-radius: 12px;
                color: {text_color};
                font-size: 16px;
                font-weight: bold;
                padding: 0px;
                min-width: 24px;
                max-width: 24px;
                min-height: 24px;
                max-height: 24px;
            }}
            QPushButton#KeywordChipRemoveButton:hover {{
                background-color: rgba(255, 255, 255, 0.2);
            }}
            """
        )

    @property
    def text(self) -> str:
        """Get the chip's text.

        Returns:
            The parameter name displayed by this chip.
        """
        return self._text

    def refresh_theme(self) -> None:
        """Re-apply theme styling after system theme change."""
        self._apply_theme()
